package dev.rdf.ksplib

import android.content.Context
import com.squareup.moshi.JsonClass
import com.squareup.moshi.Moshi

/** Its JSON adapter is generated by Moshi's KSP processor. */
@JsonClass(generateAdapter = true)
data class Greeting(val name: String, val count: Int)

object Json {
    fun roundTrip(): String {
        val adapter = Moshi.Builder().build().adapter(Greeting::class.java)
        return adapter.toJson(adapter.fromJson("""{"name":"ksp","count":3}"""))
    }

    /** A resource of this library, through this library's own R class. */
    fun label(context: Context): String = context.getString(R.string.ksp_label)
}
